const fs = require('fs');

const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
if (data.length === 0) process.exit(0);

let idx = 0;
const N = data[idx++];
const M = data[idx++];
const C = data[idx++];

const next = new Int32Array(M + 1);
const hasHater = new Uint8Array(M + 1);

for (let i = 1; i <= N; i++) {
  const A = data[idx++];
  const D = data[idx++];

  if (hasHater[D] === 0) {
    hasHater[D] = 1;
    next[D] = A;
  }
}

const seen = new Uint8Array(M + 1);
let cur = C;
let swaps = 0;

while (true) {
  if (next[cur] === 0) {
    process.stdout.write(String(swaps) + '\n');
    break;
  }

  if (seen[cur] === 1) {
    process.stdout.write('-1\n');
    break;
  }

  seen[cur] = 1;
  cur = next[cur];
  swaps++;
}
